/**
 * The types `data/perks/` exports, in one place — so a neighbouring module finds the shape it
 * needs here instead of declaring its own under a second name.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    PerkPoolKey, PerkPoolRate, PerkEntry, PerkWaveRequirementBracket, PerkFormulaDefinition, PerkLabDefinition, RandomUwPerkStat
 * depends    —
 * used by    src/data/perks/data, src/data/perks/index, src/save/catalogs/perks, src/save/catalogs/types
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */

// from data.ts

export type PerkPoolKey = 'standard' | 'ultimate_weapon' | 'trade_off'

export interface PerkPoolRate {
  pool: PerkPoolKey
  chancePercent: number
}

export interface PerkEntry {
  perk: string
  quantity: number
  pool: PerkPoolKey
}

export interface PerkWaveRequirementBracket {
  minimumPerksSelected: number
  baseWavesRequired: number
}

export interface PerkFormulaDefinition {
  name: string
  formula: string
  notes: readonly string[]
}

export interface PerkLabDefinition {
  name: string
  levels: number
  unlockRequirement: string
  behavior: string
}

export interface RandomUwPerkStat {
  weapon: string
  stoneValue: number
  effect1: string
  amount1: string
  effect2: string
  amount2: string
  effect3: string
  amount3: string
}
